import{_ as n,a,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第二册：实践与进步 · 全册语法总结 · 叙事中的时态与衔接至分词修饰与逻辑主语","description":"按课时归集语法规则、原创例句和易错边界。","frontmatter":{"title":"第二册：实践与进步 · 全册语法总结 · 叙事中的时态与衔接至分词修饰与逻辑主语","description":"按课时归集语法规则、原创例句和易错边界。","splitFrom":"life/english/new-concept/book-2/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册语法总结","summary":"按课时归集语法规则、原创例句和易错边界。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册语法总结 · 非真实条件句至时间、原因与让步从句","link":"/life/english/new-concept/book-2/grammar-part-10"},"next":{"text":"第二册：实践与进步 · 全册语法总结 · 定语从句与指代","link":"/life/english/new-concept/book-2/grammar-part-12"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册语法总结 · 非真实条件句至时间、原因与让步从句","link":"/life/english/new-concept/book-2/grammar-part-10"},"next":{"text":"第二册：实践与进步 · 全册语法总结 · 定语从句与指代","link":"/life/english/new-concept/book-2/grammar-part-12"}},"headers":[],"relativePath":"life/english/new-concept/book-2/grammar-part-11.md","filePath":"life/english/new-concept/book-2/grammar-part-11.md"}'),r={name:"life/english/new-concept/book-2/grammar-part-11.md"};function t(i,e,l,p,h,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第二册-实践与进步-·-全册语法总结-·-叙事中的时态与衔接至分词修饰与逻辑主语" tabindex="-1">第二册：实践与进步 · 全册语法总结 · 叙事中的时态与衔接至分词修饰与逻辑主语 <a class="header-anchor" href="#第二册-实践与进步-·-全册语法总结-·-叙事中的时态与衔接至分词修饰与逻辑主语" aria-label="Permalink to &quot;第二册：实践与进步 · 全册语法总结 · 叙事中的时态与衔接至分词修饰与逻辑主语&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="叙事中的时态与衔接" tabindex="-1">叙事中的时态与衔接 <a class="header-anchor" href="#叙事中的时态与衔接" aria-label="Permalink to &quot;叙事中的时态与衔接 {#叙事中的时态与衔接}&quot;">​</a></h2><p>综合叙事先建立时间线，再为每个动作选择观察角度：简单过去推进事件，过去进行交代背景，过去完成回顾更早动作。指代词应有清楚的前文对象，连接词应准确说明原因、转折或结果。并不是句子越长越好；一个句子包含多个时间层次时，应先写清主干，再添加从句。检查时分别核对事实顺序、主谓一致、动词形式和信息衔接。本课应用：was sleeping 交代风吹来时的背景；woke 表示突然醒来。叙事不必每句都写 then，可用时间从句连接重要转折。</p><p><strong>L49 原创例句：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><p>一阵风把毯子吹走时，我正睡在露台上。</p><p><strong>易错：</strong> blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">Lesson 49</a></p><h2 id="完成进行时与持续活动" tabindex="-1">完成进行时与持续活动 <a class="header-anchor" href="#完成进行时与持续活动" aria-label="Permalink to &quot;完成进行时与持续活动 {#完成进行时与持续活动}&quot;">​</a></h2><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：has been avoiding 强调持续到目前的行为；has avoided three snacks 强调次数。所谓奖励不等于健康建议，这里只练习语言表达。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：had been planting 是过去参照点之前一直进行的活动；与 have been planting 的参照点在现在不同。需要明确过去的停顿或报告时刻。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：has been leaking 强调持续泄漏及当前痕迹；has leaked a litre 强调量。两者都不自动说明泄漏此刻仍在继续，要看上下文。</p><p>现在完成进行时由 have/has been 加 -ing 构成，强调从过去持续到现在或刚刚停止且影响仍可见的活动。现在完成时更容易突出完成的数量或结果，进行形式则突出过程和时长。状态动词通常不用进行形式。for 引出时长，since 引出起点；句中有一段时间并不自动要求完成进行时，还要判断动作性质与当前是否有关联。本课应用：have been monitoring 表持续工作；have recorded three changes 则是成果数量。观察资料可支持判断，但不等于精确预知每次喷发。</p><p><strong>L51 原创例句：</strong> Tess has been avoiding sweet snacks for two weeks.</p><p>苔丝两周来一直尽量不吃甜食。</p><p><strong>L62 原创例句：</strong> The volunteers had been planting seeds for hours when the rain began.</p><p>下雨时，志愿者已经连续播种数小时了。</p><p><strong>L66 原创例句：</strong> A jar of honey has been leaking inside the delivery van.</p><p>一罐蜂蜜一直在送货车内渗漏。</p><p><strong>L67 原创例句：</strong> The scientists have been monitoring the volcano since March.</p><p>科学家们自三月以来一直在监测这座火山。</p><p><strong>易错：</strong> since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p><p>had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p><p>honey have been 错误；这里主语 a jar of honey 的核心是 jar，配 has。</p><p>since three months 不合常用表达；用 for three months 或 since March。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">Lesson 51</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-062">Lesson 62</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-066">Lesson 66</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-067">Lesson 67</a></p><h2 id="分词修饰与逻辑主语" tabindex="-1">分词修饰与逻辑主语 <a class="header-anchor" href="#分词修饰与逻辑主语" aria-label="Permalink to &quot;分词修饰与逻辑主语 {#分词修饰与逻辑主语}&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Waving a flag 的逻辑主语必须是主句的人，不能接 The gate was opened 而让门成为挥旗者。分词状语可压缩同主语动作。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：a car called ... 中 called 是过去分词后置定语，等于 that is called；它不是主句谓语，所以句子还需要 ran、reached 等谓语。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Dressed as a worker 描述主句人物的被动装扮状态，不等于正在给别人穿衣；dressing a worker 则是主动动作，意义不同。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Hearing a strange sound 的主语应与主句司机一致；如果主句主语变成 steering wheel，就产生逻辑错误。分词开头不能掩盖谁做动作。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：fried potatoes 中 fried 表经过油炸处理的状态；frying potatoes 可指正在炸土豆的动作，不能仅看 -ing 就当形容词。</p><p><strong>L70 原创例句：</strong> Waving a red flag, the steward guided the visitors away.</p><p>工作人员挥着红旗，引导游客离开。</p><p><strong>L72 原创例句：</strong> A car called Silver Finch completed three test runs.</p><p>一辆名为“银雀”的车完成了三次试跑。</p><p><strong>L81 原创例句：</strong> Dressed as a cleaner, the prisoner walked towards the side gate.</p><p>那个囚犯扮成清洁工，向侧门走去。</p><p><strong>L86 原创例句：</strong> Hearing a strange sound, the driver slowed down immediately.</p><p>听到异常声音后，司机立即减速。</p><p><strong>L90 原创例句：</strong> The potatoes fried this morning were used for supper.</p><p>今天早上炸好的土豆被用于晚餐。</p><p><strong>易错：</strong> Waving a flag, the visitors were moved 会让逻辑主语变成游客，不一定符合想表达的意思。</p><p>A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p><p>Dressed as a cleaner, the gate opened 会使分词逻辑主语变成门，形成悬垂结构。</p><p>Hearing a sound, the wheel broke 让 wheel 成听声者，不符合意思。</p><p>We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">Lesson 70</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-072">Lesson 72</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-081">Lesson 81</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-086">Lesson 86</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-090">Lesson 90</a></p>',49)])])}const f=n(r,[["render",t]]);export{d as __pageData,f as default};
